test('createInvoice accepts no discount (defaults to 0)', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice accepts valid discount percentages', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 50 },
      { sku: 'SUPPORT-HOUR', qty: 5, discountPercent: 12.5 },
      { sku: 'ICON-SET', qty: 20, discountPercent: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
  assert.equal(result.value.lines[1].discountPercent, 50);
  assert.equal(result.value.lines[2].discountPercent, 12.5);
  assert.equal(result.value.lines[3].discountPercent, 100);
});

test('createInvoice reports DISCOUNT_INVALID for invalid discounts', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: -1 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 'fifty' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: NaN }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('lineDiscount calculates correct discount amount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 50 }), 5000);
  assert.equal(lineDiscount({ qty: 3, unitPrice: 333, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 1, unitPrice: 1000, discountPercent: 100 }), 1000);
});

test('lineDiscount defaults to 0 when discountPercent is undefined', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000 }), 0);
});

test('lineDiscount clamps to 0 (never negative)', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 50 };
  const discount = lineDiscount(line);
  assert.ok(discount >= 0);
});

test('invoiceTotals includes subtotal, discount, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 120000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.total, 95000 - 9500 + 120000);
});

test('invoiceTotals calculates zero discount when no discounts applied', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 150 }],
  };

  const totals = invoiceTotals(invoice);

  assert.ok(totals.total >= 0);
});

test('addLine accepts discount percentage', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'LOGO-PACK', qty: 1, discountPercent: 25 });
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines[1].discountPercent, 25);
});

test('addLine reports DISCOUNT_INVALID for invalid discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
