import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-02-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  const line1 = result.value.lines[0];
  assert.equal(line1.sku, 'DEV-HOUR');
  assert.equal(line1.name, 'Development (hour)');
  assert.equal(line1.qty, 10);
  assert.equal(line1.unitPrice, 9500);
  assert.equal(line1.vatRate, 21);

  const line2 = result.value.lines[1];
  assert.equal(line2.sku, 'LOGO-PACK');
  assert.equal(line2.name, 'Logo package');
  assert.equal(line2.qty, 1);
  assert.equal(line2.unitPrice, 120000);
  assert.equal(line2.vatRate, 21);
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for bad format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024/02/15',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '15-02-2024',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for non-existent dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-04-31',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice accepts valid dates including leap days', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES when lines is missing', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for non-positive quantities', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: '10' }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for product not in catalogue', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate the input array', () => {
  const lines = [
    { sku: 'DEV-HOUR', qty: 10 },
    { sku: 'LOGO-PACK', qty: 1 },
  ];
  const originalJSON = JSON.stringify(lines);

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines,
  });

  assert.equal(JSON.stringify(lines), originalJSON);
});

test('lineTotal calculates qty * unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal returns whole cents', () => {
  const line = { qty: 3, unitPrice: 333 };
  const total = lineTotal(line);
  assert.equal(total, 999);
  assert.equal(total % 1, 0);
});

test('invoiceTotals returns correct subtotal, discount, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 95000 + 120000,
    discount: 0,
    total: 95000 + 120000,
  });
});

test('invoiceTotals with single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'SUPPORT-HOUR', qty: 5 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 7250);
  assert.equal(totals.total, 5 * 7250);
});

test('invoiceTotals with many lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'COPY-HOUR', qty: 5 },
      { sku: 'SUPPORT-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 20 },
    ],
  }).value;

  const expected = 10 * 9500 + 5 * 6000 + 3 * 7250 + 20 * 980;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals returns whole cents', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'PHOTO-LIC', qty: 3 },
      { sku: 'FONT-LIC', qty: 2 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal % 1, 0);
  assert.equal(totals.total % 1, 0);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 2);
  assert.equal(newInvoice.lines[1].sku, 'LOGO-PACK');
  assert.equal(newInvoice.lines[1].qty, 1);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 1);
  assert.equal(newInvoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(newInvoice.lines[0].qty, 8);
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const originalJSON = JSON.stringify(invoice);
  addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(JSON.stringify(invoice), originalJSON);
});

test('addLine reports QTY_INVALID for bad quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 1.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine reports UNKNOWN_SKU for invalid SKU', () => {
