    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'INVALID-SKU', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
