    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const nonDraftInvoice = { ...invoice, status: 'sent' };

  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'LOGO-PACK', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine removes a line from an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'SUPPORT-HOUR', qty: 3 },
    ],
  }).value;

  const result = removeLine(invoice, 'LOGO-PACK');
