  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 2);
  assert.equal(newInvoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(newInvoice.lines[1].sku, 'SUPPORT-HOUR');
});

test('removeLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const originalJSON = JSON.stringify(invoice);
