test('createInvoice uses tier discount in calculations', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const expected = 10 * 9500;
  const tierDiscount = (expected * 5) / 100;

  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, Math.round(tierDiscount));
  assert.equal(totals.total, expected - Math.round(tierDiscount));
});

