import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('renderInvoiceText shows DRAFT for draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number when issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
});

test('renderInvoiceText shows customer ID', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Customer: C-003');
});

test('renderInvoiceText formats a single line item', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
});

test('renderInvoiceText formats multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
  assert.equal(lines[3], '1 x Logo package @ €1,200.00 = €1,200.00');
});

test('renderInvoiceText shows total on last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[4], 'Total: €2,150.00');
});

test('renderInvoiceText formats amounts in euros', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'STICKER', qty: 100 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '100 x Sticker sheet @ €0.50 = €50.00');
  assert.equal(lines[3], '12 x Website hosting (month) @ €15.00 = €180.00');
  assert.equal(lines[4], 'Total: €230.00');
});

test('renderInvoiceText shows complete invoice with issued number', () => {
  const invoice = createInvoice({
    customerId: 'C-005',
    issueDate: '2024-03-20',
    lines: [
      { sku: 'COPY-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  }).value;

  const issued = issueInvoice(invoice, ['INV-2024-0001']).value;
  const text = renderInvoiceText(issued);

  const expected =
    'INV-2024-0002\n' +
    'Customer: C-005\n' +
    '8 x Copywriting (hour) @ €60.00 = €480.00 (2.5% discount: -€12.00)\n' +
    '5 x Icon set (24 icons) @ €9.80 = €49.00 (2.5% discount: -€1.22)\n' +
    'Subtotal: €529.00\n' +
    'Discount: -€13.22\n' +
    'Total: €515.78';

  assert.equal(text, expected);
});

test('renderInvoiceText renders as single string with newlines', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.equal(typeof text, 'string');
  assert.ok(text.includes('\n'));
  const lines = text.split('\n');
  assert.equal(lines.length, 4);
});

test('renderInvoiceText shows discount on line item', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(10% discount: -€95.00)'));
});

test('renderInvoiceText shows decimal discount percentage', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(12.5% discount: -€118.75)'));
});

test('renderInvoiceText shows subtotal and discount when discounts present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines.some((line) => line.startsWith('Subtotal:')));
  assert.ok(lines.some((line) => line.startsWith('Discount:')));
  assert.ok(lines.some((line) => line.startsWith('Total:')));
});

test('renderInvoiceText formats discount line correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00 (10% discount: -€95.00)');
  assert.equal(lines[3], 'Subtotal: €950.00');
  assert.equal(lines[4], 'Discount: -€95.00');
  assert.equal(lines[5], 'Total: €855.00');
});

test('renderInvoiceText does not show discount line if discount is 0', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(!text.includes('Subtotal:'));
  assert.ok(!text.includes('Discount:'));
  assert.ok(lines.some((line) => line.startsWith('Total:')));
  assert.equal(lines.length, 4);
});

test('renderInvoiceText shows multiple lines with mixed discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-005',
    issueDate: '2024-03-20',
    lines: [
      { sku: 'COPY-HOUR', qty: 8, discountPercent: 5 },
      { sku: 'ICON-SET', qty: 5, discountPercent: 0 },
      { sku: 'DOMAIN-YEAR', qty: 2, discountPercent: 15 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(5% discount: -€24.00)'));
  assert.ok(!lines[3].includes('discount'));
  assert.ok(lines[4].includes('(15% discount: -€3.90)'));
  assert.ok(lines.some((line) => line.startsWith('Subtotal:')));
  assert.ok(lines.some((line) => line.startsWith('Discount:')));
});

